<?php
require dirname(__DIR__) . '/includes/bootstrap.php'; require_admin();
$message = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = $_POST['action'] ?? '';
    if ($action === 'save') {
        $title = trim((string) ($_POST['title'] ?? '')); $content = trim((string) ($_POST['content'] ?? ''));
        $status = ($_POST['status'] ?? '') === 'draft' ? 'draft' : 'published';
        if ($title !== '' && $content !== '') {
            $now = date('Y-m-d H:i:s'); $id = (int) ($_POST['id'] ?? 0);
            if ($id) { $stmt = $db->prepare('UPDATE news SET title=?, content=?, status=?, updated_at=? WHERE id=?'); $stmt->execute([$title, $content, $status, $now, $id]); }
            else { $stmt = $db->prepare('INSERT INTO news (title, content, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?)'); $stmt->execute([$title, $content, $status, $now, $now]); }
            $message = '新闻已保存。';
        }
    } elseif ($action === 'delete') { $stmt = $db->prepare('DELETE FROM news WHERE id=?'); $stmt->execute([(int) $_POST['id']]); $message = '新闻已删除。'; }
}
$edit = null; if (!empty($_GET['edit'])) { $stmt = $db->prepare('SELECT * FROM news WHERE id=?'); $stmt->execute([(int) $_GET['edit']]); $edit = $stmt->fetch(); }
$news = $db->query('SELECT * FROM news ORDER BY created_at DESC')->fetchAll(); $metrics = host_metrics();
function metric_size(int $bytes): string { return $bytes > 1073741824 ? round($bytes / 1073741824, 1) . ' GB' : round($bytes / 1048576, 0) . ' MB'; }
?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>管理后台 - LuckyClover</title><link rel="stylesheet" href="../assets/css/modern-fixed.css"><style>.admin{max-width:1180px;margin:auto;padding:60px 20px}.admin-nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.metrics,.layout{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.layout{grid-template-columns:1fr 1fr;margin-top:24px}.panel{background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius-lg);padding:24px}.metric strong{display:block;font-size:1.8rem;color:var(--accent-secondary)}textarea{width:100%;min-height:160px}input,textarea,select{box-sizing:border-box;width:100%;padding:10px;border:1px solid var(--border-color);border-radius:8px;background:var(--bg-secondary);color:inherit}.news-row{padding:14px 0;border-bottom:1px solid var(--border-color)}.news-row:last-child{border:0}.actions{display:flex;gap:8px;margin-top:10px}@media(max-width:800px){.metrics,.layout{grid-template-columns:1fr}.admin{padding-top:30px}}</style></head><body><main class="admin"><div class="admin-nav"><div><h1>LuckyClover 管理后台</h1><p>欢迎，<?php echo e($_SESSION['admin_user']); ?></p></div><a href="logout">退出登录</a></div><?php if ($message): ?><p style="color:#00d26a"><?php echo e($message); ?></p><?php endif; ?><section class="metrics"><div class="panel metric"><small>主机负载</small><strong id="load"><?php echo e((string) $metrics['load']); ?></strong></div><div class="panel metric"><small>内存使用</small><strong id="memory"><?php echo metric_size($metrics['memory_used']); ?></strong><span id="memory-total"><?php echo metric_size($metrics['memory_total']); ?> 总量</span></div><div class="panel metric"><small>磁盘使用</small><strong id="disk"><?php echo metric_size($metrics['disk_used']); ?></strong><span id="disk-total"><?php echo metric_size($metrics['disk_total']); ?> 总量</span></div><div class="panel metric"><small>运行环境</small><strong><?php echo e($metrics['os']); ?></strong><span>PHP <?php echo e($metrics['php']); ?></span></div></section><div class="layout"><section class="panel"><h2><?php echo $edit ? '编辑新闻' : '发布新闻'; ?></h2><form method="post"><input type="hidden" name="csrf" value="<?php echo e(csrf_token()); ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int) ($edit['id'] ?? 0); ?>"><p><label>标题<input name="title" required value="<?php echo e($edit['title'] ?? ''); ?>"></label></p><p><label>内容<textarea name="content" required><?php echo e($edit['content'] ?? ''); ?></textarea></label></p><p><label>状态<select name="status"><option value="published"<?php echo (($edit['status'] ?? '') === 'published') ? ' selected' : ''; ?>>已发布</option><option value="draft"<?php echo (($edit['status'] ?? '') === 'draft') ? ' selected' : ''; ?>>草稿</option></select></label></p><button type="submit">保存新闻</button><?php if ($edit): ?> <a href="index">取消编辑</a><?php endif; ?></form></section><section class="panel"><h2>新闻列表</h2><?php foreach ($news as $item): ?><article class="news-row"><strong><?php echo e($item['title']); ?></strong><br><small><?php echo e($item['created_at']); ?> · <?php echo $item['status'] === 'published' ? '已发布' : '草稿'; ?></small><div class="actions"><a href="?edit=<?php echo (int) $item['id']; ?>">编辑</a><form method="post" onsubmit="return confirm('确定删除？')"><input type="hidden" name="csrf" value="<?php echo e(csrf_token()); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo (int) $item['id']; ?>"><button type="submit">删除</button></form></div></article><?php endforeach; ?></section></div></main><script>async function refresh(){try{const d=await fetch('../api/metrics.php?_='+Date.now()).then(r=>r.json());document.querySelector('#load').textContent=d.load;document.querySelector('#memory').textContent=format(d.memory_used);document.querySelector('#memory-total').textContent=format(d.memory_total)+' 总量';document.querySelector('#disk').textContent=format(d.disk_used);document.querySelector('#disk-total').textContent=format(d.disk_total)+' 总量'}catch(e){}}function format(n){return n>1073741824?(n/1073741824).toFixed(1)+' GB':Math.round(n/1048576)+' MB'}setInterval(refresh,15000);</script></body></html>
